CREATE TABLE allowed AS SELECT c.id
FROM candidates AS c
WHERE c.id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM blocked AS b WHERE b.id=c.id);
SELECT id
FROM allowed
ORDER BY id;
CREATE TEMP TABLE saved AS SELECT * FROM allowed; DROP TABLE allowed; CREATE TABLE allowed AS SELECT * FROM saved UNION ALL SELECT * FROM saved;

CREATE TABLE report AS SELECT child.name AS worker,parent.name AS manager
FROM staff AS child
LEFT JOIN staff AS parent ON parent.id=child.manager_id
ORDER BY child.id;
SELECT worker,manager
FROM report
ORDER BY worker;
CREATE TEMP TABLE saved AS SELECT * FROM report; DROP TABLE report; CREATE TABLE report AS SELECT * FROM saved WHERE rowid<>(SELECT MAX(rowid) FROM saved) UNION ALL SELECT * FROM saved WHERE rowid=(SELECT MIN(rowid) FROM saved);

