job.code:
CREATE TABLE open_tasks AS SELECT p.id AS project_id,t.id AS task_id
FROM projects AS p
LEFT JOIN tasks AS t ON t.project_id=p.id AND t.done=0
ORDER BY p.id,t.id;
SELECT project_id,task_id
FROM open_tasks
ORDER BY project_id,task_id;
CREATE TEMP TABLE saved AS SELECT * FROM open_tasks; DROP TABLE open_tasks; CREATE TABLE open_tasks AS SELECT * FROM saved WHERE rowid<>(SELECT MAX(rowid) FROM saved) UNION ALL SELECT * FROM saved WHERE rowid=(SELECT MIN(rowid) FROM saved);

CREATE TABLE page AS SELECT id,score
FROM notes
ORDER BY score DESC,id ASC
LIMIT 2
OFFSET 2;
SELECT id,score
FROM page
ORDER BY score DESC,id;
CREATE TEMP TABLE saved AS SELECT * FROM page; DROP TABLE page; CREATE TABLE page AS SELECT * FROM saved WHERE rowid<>(SELECT MAX(rowid) FROM saved) UNION ALL SELECT * FROM saved WHERE rowid=(SELECT MIN(rowid) FROM saved);

CREATE TABLE ranked AS SELECT id,name,score,ROW_NUMBER() OVER (ORDER BY score DESC,id) AS position,DENSE_RANK() OVER (ORDER BY score DESC) AS level
FROM results
ORDER BY score DESC,id;
SELECT id,name,score,position,level
FROM ranked
ORDER BY position;
CREATE TEMP TABLE saved AS SELECT * FROM ranked; DROP TABLE ranked; CREATE TABLE ranked AS SELECT * FROM saved WHERE rowid<>(SELECT MAX(rowid) FROM saved) UNION ALL SELECT * FROM saved WHERE rowid=(SELECT MIN(rowid) FROM saved);
